CREATE UNIQUE INDEX IF NOT EXISTS "idx_fleet_spares_uuid" ON "fleet_spares" USING btree ("fleet_spares_uuid");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "idx_fleet_spares_component_uuid" ON "fleet_spares" USING btree ("fleet_components_uuid");